/* prog30_escape_unescape.c
 * Reimplementation of the original program whose binary is named
 * prog30_escape_unescape.  The program accepts three command line
 * arguments:
 *
 *   prog30_escape_unescape <mode> <string>
 *
 *   <mode>   – either "escape" or "unescape"
 *   <string> – the text to be processed
 *
 * The result is printed with puts() (i.e. a trailing newline is added).
 *
 * If the arguments are missing or the mode is not recognised the program
 * prints a short message and exits.
 *
 * The implementation follows the behaviour observed in the decompiled
 * binary, but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT_LEN 1023   /* original binary limited the input to 0x3FF */

static void escape_string(const char *src, char *dst)
{
    while (*src) {
        switch (*src) {
            case '\\':
                *dst++ = '\\';
                *dst++ = '\\';
                break;
            case '"':
                *dst++ = '\\';
                *dst++ = '"';
                break;
            case '\n':
                *dst++ = '\\';
                *dst++ = 'n';
                break;
            case '\t':
                *dst++ = '\\';
                *dst++ = 't';
                break;
            default:
                *dst++ = *src;
                break;
        }
        src++;
    }
    *dst = '\0';
}

static void unescape_string(const char *src, char *dst)
{
    while (*src) {
        if (*src == '\\' && src[1] != '\0') {
            char esc = src[1];
            switch (esc) {
                case '\\':
                    *dst++ = '\\';
                    break;
                case '"':
                    *dst++ = '"';
                    break;
                case 'n':
                    *dst++ = '\n';
                    break;
                case 't':
                    *dst++ = '\t';
                    break;
                default:
                    /* Unknown escape – copy the character after the backslash */
                    *dst++ = esc;
                    break;
            }
            src += 2;   /* skip the backslash and the escaped character */
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT_LEN) {
        puts("USAGE");
        return 0;
    }

    /* Allocate a buffer that is certainly large enough.
       In the worst case every character becomes two characters. */
    char *out = malloc(strlen(input) * 2 + 2);
    if (!out) {
        perror("malloc");
        return 1;
    }

    if (strcmp(mode, "escape") == 0) {
        escape_string(input, out);
        puts(out);
    } else if (strcmp(mode, "unescape") == 0) {
        unescape_string(input, out);
        puts(out);
    } else {
        puts("INVALID_MODE");
    }

    free(out);
    return 0;
}
